#
# common.jl
#
# Parser and point-wise comparison tools for the plain-text NESSi reference
# data (format kbref-v1, generated by .nessi/kbref/generate.sh).
#
# Index translation (NESSi is 0-based, KB is 1-based):
#
#   mat[q]    -> G.mat[q+1]
#   ret[i,j]  -> G.ret[i+1,j+1]       (0 ≤ j ≤ i ≤ nt)
#   tv[i,q]   -> G.lmix[i+1,q+1]
#   les[i,j]  -> G.less[i+1,j+1]      (0 ≤ i ≤ j ≤ nt)
#
# KB ntime = NESSi nt + 1, KB ntau = NESSi ntau + 1.
#

using Test
using Printf
using KadanoffBaym

#=
### *kbref-v1 Schema*
=#

const KBREF_VERSION = "1"
const KBREF_COLUMNS = "component i j a b re im"
const KBREF_KINDS = ("weights", "herm_matrix",
                     "scalar", "function", "element", "labels")
const KBREF_COMPONENTS = Dict(
    "weights"     => ("greg", "bd", "pint", "pdiff", "rcorr"),
    "herm_matrix" => ("mat", "ret", "tv", "les"),
    "scalar"      => ("distance_ret", "distance_tv", "distance_les",
                      "distance_total", "response"),
    "function"    => ("extrapolate", "interpolate"),
    "element"     => ("les_timediag", "density_matrix",
                      "startup_less_adv", "startup_lmix_rmix"),
    "labels"      => ("order", "alpha"),
)
#
# Data kinds introduced in P2. They require the metadata `generator` and
# `case_set`.
const KBREF_P2_KINDS = ("scalar", "function", "element", "labels")

"""
    KbrefRow

One data line of a kbref-v1 file: `component i j a b re im`.
"""
struct KbrefRow
    component :: String
    i :: Int
    j :: Int
    a :: Int
    b :: Int
    value :: ComplexF64
end

"""
    KbrefData

Content of a kbref-v1 file: metadata (key => value) and data rows.
"""
struct KbrefData
    path :: String
    metadata :: Dict{String,String}
    rows :: Vector{KbrefRow}
end

kbref_error(path, ln, msg) = throw(ArgumentError("kbref: $path:$ln: $msg"))

function kbref_int(md::Dict{String,String}, key::String, path)
    haskey(md, key) || kbref_error(path, 0, "missing metadata `$key`")
    v = tryparse(Int, md[key])
    v === nothing && kbref_error(path, 0, "metadata `$key` is not an integer")
    return v
end

"""
    kbref_check_weights(r::KbrefRow, path, ln)

Validate the index domain of a weight table entry.
"""
function kbref_check_weights(r::KbrefRow, path, ln)
    k = r.i
    1 ≤ k ≤ 5 || kbref_error(path, ln, "k = $k out of range 1:5")
    imag(r.value) == 0.0 || kbref_error(path, ln, "weights must be real")
    if r.component == "greg"
        n, j = r.j, r.a
        ok = 0 ≤ n ≤ 2k + 3 && 0 ≤ j ≤ max(n, k) && r.b == -1
    elseif r.component == "bd"
        ok = 0 ≤ r.j ≤ k + 1 && r.a == -1 && r.b == -1
    elseif r.component == "pint"
        ok = 0 ≤ r.j ≤ k && 0 ≤ r.a ≤ k && 0 ≤ r.b ≤ k
    elseif r.component == "pdiff"
        ok = 0 ≤ r.j ≤ k && 0 ≤ r.a ≤ k && r.b == -1
    else # rcorr
        ok = 2 ≤ k && 1 ≤ r.j ≤ k - 1 && 0 ≤ r.a ≤ k && 0 ≤ r.b ≤ k
    end
    ok || kbref_error(path, ln, "index out of range for `$(r.component)`")
end

"""
    kbref_check_herm(r::KbrefRow, nt, ntau, s1, s2, path, ln)

Validate the index domain of a herm_matrix entry.
"""
function kbref_check_herm(r::KbrefRow, nt, ntau, s1, s2, path, ln)
    (0 ≤ r.a < s1 && 0 ≤ r.b < s2) ||
        kbref_error(path, ln, "orbital index out of range")
    c, i, j = r.component, r.i, r.j
    if c == "mat"
        ok = 0 ≤ i ≤ ntau && j == -1
    elseif c == "ret"
        ok = 0 ≤ j ≤ i ≤ nt
    elseif c == "tv"
        ok = 0 ≤ i ≤ nt && 0 ≤ j ≤ ntau
    else # les
        ok = 0 ≤ i ≤ j ≤ nt
    end
    ok || kbref_error(path, ln, "index out of range for `$c`")
end

"""
    kbref_check_p2(r::KbrefRow, md, path, ln)

Validate the index domain of a scalar/function/element/labels entry.
"""
function kbref_check_p2(r::KbrefRow, md::Dict{String,String}, path, ln)
    kind = md["data_kind"]
    c = r.component
    r.i ≥ 0 || kbref_error(path, ln, "negative case_id")
    if kind == "scalar" || kind == "labels"
        (r.j == -1 && r.a == -1 && r.b == -1) ||
            kbref_error(path, ln, "index out of range for `$c`")
        if startswith(c, "distance")
            imag(r.value) == 0.0 || kbref_error(path, ln, "distance must be real")
        elseif c == "order"
            v = real(r.value)
            (imag(r.value) == 0.0 && isinteger(v) && 0 ≤ v ≤ 5) ||
                kbref_error(path, ln, "bad order label")
        end
    else # function, element
        nt = kbref_int(md, "nt", path)
        s1 = kbref_int(md, "size1", path)
        s2 = kbref_int(md, "size2", path)
        (0 ≤ r.a < s1 && 0 ≤ r.b < s2) ||
            kbref_error(path, ln, "orbital index out of range")
        if c == "interpolate"
            haskey(md, "tinter") || kbref_error(path, ln, "missing metadata `tinter`")
            r.j == -1 || kbref_error(path, ln, "index out of range for `$c`")
        elseif startswith(c, "startup")
            0 ≤ r.j ≤ nt || kbref_error(path, ln, "index out of range for `$c`")
        else
            -1 ≤ r.j ≤ nt || kbref_error(path, ln, "index out of range for `$c`")
        end
    end
end

"""
    read_kbref(path::AbstractString)

Read and strictly validate a kbref-v1 file. Throws `ArgumentError` for any
violation of the schema (version, data_kind, columns, component names,
index domain, finite values, duplicated keys, completeness).
"""
function read_kbref(path::AbstractString)
    md = Dict{String,String}()
    rows = KbrefRow[]
    keys = Set{NTuple{5,Any}}()
    header = false
    data_started = false
    #
    for (ln, line) in enumerate(eachline(path))
        s = strip(line)
        isempty(s) && kbref_error(path, ln, "empty line")
        if startswith(s, "#")
            data_started && kbref_error(path, ln, "metadata after data")
            body = strip(s[2:end])
            parts = split(body; limit = 2)
            length(parts) == 2 || kbref_error(path, ln, "bad metadata line")
            key, val = String(parts[1]), String(strip(parts[2]))
            if !header
                (key == "kbref" && val == KBREF_VERSION) ||
                    kbref_error(path, ln, "first line must be `# kbref 1`")
                header = true
                continue
            end
            haskey(md, key) && kbref_error(path, ln, "duplicated metadata `$key`")
            md[key] = val
            continue
        end
        #
        header || kbref_error(path, ln, "missing `# kbref 1` header")
        if !data_started
            kind = get(md, "data_kind", "")
            kind in KBREF_KINDS ||
                kbref_error(path, ln, "unknown data_kind `$kind`")
            if kind in KBREF_P2_KINDS || startswith(get(md, "generator", ""), "p2_")
                for key in ("generator", "case_set")
                    haskey(md, key) || kbref_error(path, ln, "missing metadata `$key`")
                end
            end
            if kind == "herm_matrix" && startswith(get(md, "generator", ""), "p2_")
                v = tryparse(Int, get(md, "case_id", ""))
                (v !== nothing && v ≥ 0) ||
                    kbref_error(path, ln, "missing or bad metadata `case_id`")
            end
            get(md, "columns", "") == KBREF_COLUMNS ||
                kbref_error(path, ln, "bad columns specification")
            data_started = true
        end
        #
        f = split(s)
        length(f) == 7 || kbref_error(path, ln, "expected 7 columns, got $(length(f))")
        comp = String(f[1])
        comp in KBREF_COMPONENTS[md["data_kind"]] ||
            kbref_error(path, ln, "unknown component `$comp`")
        idx = map(x -> tryparse(Int, x), f[2:5])
        any(isnothing, idx) && kbref_error(path, ln, "bad integer index")
        re = tryparse(Float64, f[6])
        im = tryparse(Float64, f[7])
        (re === nothing || im === nothing) && kbref_error(path, ln, "bad number")
        (isfinite(re) && isfinite(im)) || kbref_error(path, ln, "non-finite value")
        row = KbrefRow(comp, idx..., complex(re, im))
        #
        if md["data_kind"] == "weights"
            kbref_check_weights(row, path, ln)
        elseif md["data_kind"] in KBREF_P2_KINDS
            kbref_check_p2(row, md, path, ln)
        else
            nt = kbref_int(md, "nt", path)
            ntau = kbref_int(md, "ntau", path)
            s1 = kbref_int(md, "size1", path)
            s2 = kbref_int(md, "size2", path)
            kbref_check_herm(row, nt, ntau, s1, s2, path, ln)
        end
        #
        key = (comp, idx...)
        key in keys && kbref_error(path, ln, "duplicated key $key")
        push!(keys, key)
        push!(rows, row)
    end
    #
    header || kbref_error(path, 0, "missing `# kbref 1` header")
    data_started || kbref_error(path, 0, "no data rows")
    #
    # Completeness of the independent storage domain
    if md["data_kind"] == "herm_matrix"
        nt = kbref_int(md, "nt", path)
        ntau = kbref_int(md, "ntau", path)
        s = kbref_int(md, "size1", path) * kbref_int(md, "size2", path)
        ntri = (nt + 1) * (nt + 2) ÷ 2
        nexp = s * ((ntau + 1) + 2 * ntri + (nt + 1) * (ntau + 1))
        length(rows) == nexp ||
            kbref_error(path, 0, "incomplete data: $(length(rows)) rows, expected $nexp")
    end
    #
    return KbrefData(String(path), md, rows)
end

"""
    write_kbref(path, data_kind, meta, rows)

Write a kbref-v1 file. It is used by the schema round-trip tests only.
"""
function write_kbref(path::AbstractString, data_kind::String,
                     meta::Vector{Pair{String,String}}, rows::Vector{KbrefRow})
    open(path, "w") do io
        println(io, "# kbref 1")
        println(io, "# data_kind ", data_kind)
        for (k, v) in meta
            println(io, "# ", k, " ", v)
        end
        println(io, "# columns ", KBREF_COLUMNS)
        for r in rows
            @printf(io, "%s %d %d %d %d %.17e %.17e\n",
                    r.component, r.i, r.j, r.a, r.b, real(r.value), imag(r.value))
        end
    end
end

"""
    labels_by_case(labels::KbrefData, cases; order, alpha)

Join the labels with the data cases. `cases` is the collection of
`case_id` used by the data files. `order` and `alpha` are either `Bool`
(the same requirement for all cases) or a collection of the `case_id`
which require the label. Every case must have exactly one `order` label
if it is required and none otherwise, and likewise for `alpha`. Labels
referring to unknown cases are rejected. Returns
`Dict(case_id => (order = ..., alpha = ...))`, where the missing labels
are `nothing`.
"""
function labels_by_case(labels::KbrefData, cases; order, alpha)
    need(req::Bool, c) = req
    need(req, c) = c in req
    path = labels.path
    labels.metadata["data_kind"] == "labels" ||
        kbref_error(path, 0, "not a labels file")
    cs = Set{Int}(cases)
    ord = Dict{Int,Int}()
    alp = Dict{Int,ComplexF64}()
    for r in labels.rows
        r.i in cs || kbref_error(path, 0, "label refers to unknown case $(r.i)")
        if r.component == "order"
            need(order, r.i) || kbref_error(path, 0, "unexpected order label for case $(r.i)")
            ord[r.i] = Int(real(r.value))
        else
            need(alpha, r.i) || kbref_error(path, 0, "unexpected alpha label for case $(r.i)")
            alp[r.i] = r.value
        end
    end
    for c in cs
        need(order, c) && !haskey(ord, c) && kbref_error(path, 0, "missing order label for case $c")
        need(alpha, c) && !haskey(alp, c) && kbref_error(path, 0, "missing alpha label for case $c")
    end
    return Dict(c => (order = get(ord, c, nothing), alpha = get(alp, c, nothing))
                for c in cs)
end

#=
### *Translation and Point-wise Comparison*
=#

"""
    kb_value(G::ℱ, row::KbrefRow)

Return the KB value corresponding to a herm_matrix reference entry.
"""
function kb_value(G::ℱ, row::KbrefRow)
    i, j, a, b = row.i, row.j, row.a + 1, row.b + 1
    c = row.component
    if c == "mat"
        return G.mat[i+1][a,b]
    elseif c == "ret"
        return G.ret[i+1,j+1][a,b]
    elseif c == "tv"
        return G.lmix[i+1,j+1][a,b]
    elseif c == "les"
        return G.less[i+1,j+1][a,b]
    end
    error("kbref: unknown component $c")
end

kb_index(row::KbrefRow) = row.component == "mat" ? "[$(row.i+1)]" :
                                                    "[$(row.i+1),$(row.j+1)]"

"""
    test_kbref(G::ℱ, ref::KbrefData; atol = 1e-10, rtol = 1e-10)

Compare every reference entry with the KB Green's function `G`. Returns
the maximal absolute error per component.
"""
function test_kbref(G::ℱ, ref::KbrefData; atol = 1e-10, rtol = 1e-10)
    md = ref.metadata
    @test md["data_kind"] == "herm_matrix"
    @test getntime(G) == parse(Int, md["nt"]) + 1
    @test getntau(G) == parse(Int, md["ntau"]) + 1
    @test getdims(G) == (parse(Int, md["size1"]), parse(Int, md["size2"]))
    #
    errs = Dict("mat" => 0.0, "ret" => 0.0, "tv" => 0.0, "les" => 0.0)
    nfail = 0
    for row in ref.rows
        v = kb_value(G, row)
        err = abs(v - row.value)
        errs[row.component] = max(errs[row.component], err)
        if !isapprox(v, row.value; atol = atol, rtol = rtol)
            nfail += 1
            nfail ≤ 10 && @error "kbref mismatch" case = md["case"] component = row.component nessi = (row.i, row.j) kb = kb_index(row) orbital = (row.a, row.b) nessi_value = row.value kb_value = v
        end
    end
    @test nfail == 0
    return errs
end

"""
    weight_value(row::KbrefRow)

Return the KB weight corresponding to a weight table entry.
"""
function weight_value(row::KbrefRow)
    I = Integrator(row.i)
    c = row.component
    if c == "greg"
        return I.GIW[row.j,row.a]
    elseif c == "bd"
        return I.BDW[row.j]
    elseif c == "pint"
        return I.XIW[row.j,row.a,row.b]
    elseif c == "pdiff"
        return I.PDW[row.j,row.a]
    elseif c == "rcorr"
        return I.BCW[row.j-1,row.a,row.b]
    end
    error("kbref: unknown component $c")
end

"""
    test_weight_kbref(ref::KbrefData; atol = 2e-12, rtol = 2e-12)

Compare every weight entry with KB. Returns the maximal absolute error per
component.
"""
function test_weight_kbref(ref::KbrefData; atol = 2e-12, rtol = 2e-12)
    @test ref.metadata["data_kind"] == "weights"
    errs = Dict{String,Float64}()
    nfail = 0
    for row in ref.rows
        v = weight_value(row)
        w = real(row.value)
        errs[row.component] = max(get(errs, row.component, 0.0), abs(v - w))
        if !isapprox(v, w; atol = atol, rtol = rtol)
            nfail += 1
            nfail ≤ 10 && @error "kbref weight mismatch" component = row.component k = row.i index = (row.j, row.a, row.b) nessi_value = w kb_value = v
        end
    end
    @test nfail == 0
    return errs
end
